diff --git a/mailnews/protocols/exchange/src/ExchangeFolder.cpp b/mailnews/protocols/exchange/src/ExchangeFolder.cpp
index f56c67f796a..650c4906290 100644
--- a/mailnews/protocols/exchange/src/ExchangeFolder.cpp
+++ b/mailnews/protocols/exchange/src/ExchangeFolder.cpp
@@ -979,16 +979,15 @@ nsresult ExchangeFolder::HandleDeleteOperation(

   // If any ancestor of this folder is the trash folder, then hard delete.
   bool isInTrashFolder = false;
-  nsCOMPtr<nsIMsgFolder> parent;
-  GetParent(getter_AddRefs(parent));
-  while (parent) {
+  nsCOMPtr<nsIMsgFolder> folder = this;
+  while (folder) {
     bool isTrashFolder = false;
-    MOZ_TRY(parent->GetFlag(nsMsgFolderFlags::Trash, &isTrashFolder));
+    MOZ_TRY(folder->GetFlag(nsMsgFolderFlags::Trash, &isTrashFolder));
     if (isTrashFolder) {
       isInTrashFolder = true;
       break;
     }
-    parent->GetParent(getter_AddRefs(parent));
+    folder->GetParent(getter_AddRefs(folder));
   }

   // Check the delete model to see if this should be a permanent delete.
diff --git a/mailnews/protocols/exchange/test/unit/test_item_operations.js b/mailnews/protocols/exchange/test/unit/test_item_operations.js
index 4ae118cdf48..af9afbc8e84 100644
--- a/mailnews/protocols/exchange/test/unit/test_item_operations.js
+++ b/mailnews/protocols/exchange/test/unit/test_item_operations.js
@@ -907,3 +907,60 @@ add_task(async function test_hard_delete_item_ews() {
 add_task(async function test_hard_delete_item_graph() {
   await runHardDeleteTest(graphServer, graphIncomingServer);
 });
+
+/**
+ * Run a test for deleting items from the trash for the given mock/incoming
+ * server combo.
+ *
+ * @param {MockServer} mockServer
+ * @param {nsIMsgIncomingServer} incomingServer
+ */
+async function runDeleteItemFromTrashTest(mockServer, incomingServer) {
+  const rootFolder = incomingServer.rootFolder;
+  await syncFolder(incomingServer, rootFolder);
+
+  const trashFolder = rootFolder.getChildNamed("Deleted Items");
+  Assert.ok(!!trashFolder, "Trash folder should exist.");
+
+  const messages = generator.makeMessages({ count: 1 });
+  const messageId = "delete_from_trash";
+  mockServer.addItemToFolder(messageId, "deleteditems", messages[0]);
+
+  await syncFolder(incomingServer, trashFolder);
+
+  Assert.equal(
+    trashFolder.getTotalMessages(false),
+    1,
+    "Should be one message in trash"
+  );
+
+  const trashFolderMessage = [...trashFolder.messages][0];
+
+  const eventPromise = PromiseTestUtils.promiseFolderEvent(
+    trashFolder,
+    "DeleteOrMoveMsgCompleted"
+  );
+  trashFolder.deleteMessages(
+    [trashFolderMessage],
+    null,
+    false,
+    false,
+    null,
+    false
+  );
+  await eventPromise;
+
+  Assert.equal(
+    trashFolder.getTotalMessages(false),
+    0,
+    "Should be zero messages in trash"
+  );
+}
+
+add_task(async function test_delete_item_from_trash_ews() {
+  await runDeleteItemFromTrashTest(ewsServer, ewsIncomingServer);
+});
+
+add_task(async function test_delete_item_from_trash_graph() {
+  await runDeleteItemFromTrashTest(graphServer, graphIncomingServer);
+});
